installer-gui-script.script:
function check() {
    var node = '/Library/Application Support/Blackmagic Design/DaVinci Resolve/Developer/Workflow Integrations/Examples/SamplePlugin/WorkflowIntegration.node';
    if (!system.files.fileExistsAtPath(node)) {
        my.result.type = 'Fatal';
        my.result.title = 'DaVinci Resolve Studio is needed';
        my.result.message = '@NAME@ is a panel for DaVinci Resolve Studio 18 or later, and it was not found on this Mac. Install Resolve Studio first, then run this installer again.';
        return false;
    }
    return true;
}
